const LINE_META = [{"n": "東海岸線", "en": "East Coast Line", "c": "#c0392b", "d": "The spine of the island: Ōdomari on the southern harbour to Toyohara, the capital, and on up the east coast to Sakaehama. Built from 1906 as a military line and rebuilt to standard gauge, it carried everything that landed from Wakkanai."}, {"n": "川上線", "en": "Kawakami Line", "c": "#16a085", "d": "A branch inland from Konuma to the Kawakami collieries, opened in 1919 for the coal that fed Toyohara and the ships."}, {"n": "豐眞線", "en": "Hōshin Line", "c": "#8e44ad", "d": "The crossing of the island, Toyohara to Maoka on the west coast, opened through in 1928. It climbs over the watershed at Futamata and takes three hours to do fifty miles."}, {"n": "西海岸線", "en": "West Coast Line", "c": "#2980b9", "d": "The west coast from Honto north through Maoka to Tomarioru, worked as one road with the Hōshin line at Tei."}, {"n": "樺太鐵道株式會社線", "en": "Karafuto Railway Company Line", "c": "#d35400", "d": "The private railway on from Ochiai up the east coast to Shirutoru and Minami-Shinmon, opened in stages through the 1920s. Trains 3 and 4 run through from Ōdomari over the state line."}, {"n": "南樺太鐵道株式會社線", "en": "South Karafuto Railway Line", "c": "#c2185b", "d": "A short private line from Niitoi on the east coast to Rūtaka, opened in 1929."}, {"n": "南樺太炭礦鐵道株式會社線", "en": "South Karafuto Colliery Railway", "c": "#7f8c8d", "d": "The colliery railway at the southern end of the west coast, Honto to the pits at Naihoro-tanzan."}];
